const sec=document.createElement('section');sec.className='view';sec.id='frm';
sec.innerHTML=`<h1>บันทึกผลตามแบบฟอร์มราชการ</h1><p class="lead">กรอกข้อมูลในฟอร์มเดียว (รวมชื่อบริษัท ผู้รับผิดชอบ ผู้ประเมิน ผู้อนุมัติ) แล้วบันทึกเก็บไว้ ส่งออกเป็น PDF / Word ตามแบบฟอร์มของหน่วยงานได้ทุกเมื่อ</p>
<h2 style="font-size:1.05rem;margin:0 0 8px">1) เลือกแบบฟอร์มจากทะเบียนเอกสาร</h2>
<div class="tools"><input type="search" id="rq" placeholder="ค้นหารหัสเอกสาร / ชื่อเอกสาร" aria-label="ค้นหาแบบฟอร์ม"></div>
<div class="tw" style="margin-bottom:22px"><table style="min-width:760px"><thead><tr><th>รหัสเอกสาร</th><th>ชื่อเอกสาร</th><th>Revision</th><th>วันที่อนุมัติ</th><th>สถานะ</th><th>ใช้งาน</th></tr></thead><tbody id="rtb"></tbody></table></div>
<h2 style="font-size:1.05rem;margin:0 0 8px">2) บันทึกที่กรอกแล้ว</h2>
<div class="box det" id="fed"></div>
<div class="tw"><table><thead><tr><th>เอกสารเลขที่ / Rev</th><th>เครื่องมือ</th><th>วันที่สอบเทียบ</th><th>ผลสรุป</th><th>ส่งออก / จัดการ</th></tr></thead><tbody id="flist"></tbody></table></div>`;
Q('main').appendChild(sec);
const ovPill=o=>o==null?'<span class="pill p-out">ยังไม่ครบ</span>':o?'<span class="pill p-ok">ผ่านทุกรายการ</span>':'<span class="pill p-bad">มีรายการไม่ผ่าน</span>';
function list(){Q('#flist').innerHTML=RC.map((r,i)=>`<tr><td><b>${E(r.h.doc)}</b> · rev ${E(r.h.rev)}<small style="display:block;color:var(--mute)">${E(r.f.certNo||'')}</small></td><td>${E(r.f.name||'–')}<small style="display:block;color:var(--mute)">${E(r.f.asset||'')} · ${E(r.f.calco||'')}</small></td><td>${dl(r.f.calDate)||'–'}</td><td>${ovPill(overall(r))}</td><td><button class="go alt sm" data-p="${i}">พิมพ์ / PDF</button> <button class="go alt sm" data-w="${i}">Word</button> <button class="go alt sm adm" data-e="${i}">แก้ไข</button> <button class="go alt sm adm" data-x="${i}">ลบ</button></td></tr>`).join('')||'<tr><td colspan="5">ยังไม่มีบันทึก — เลือกแบบฟอร์มแล้วกด “สร้างบันทึกใหม่”</td></tr>'}
Q('#flist').onclick=e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.p!==undefined)print(RC[+d.p]);else if(d.w!==undefined)word(RC[+d.w]);else if(d.e!==undefined){idx=+d.e;cur=JSON.parse(JSON.stringify(RC[idx]));draw()}
 else if(d.x!==undefined&&confirm('ลบบันทึกนี้?')){const r=RC.splice(+d.x,1)[0];log('ลบบันทึกแบบฟอร์ม',r.h.doc,{เครื่อง:r.f.name},null);list();toast('ลบแล้ว')}};
